package main

import (
	"fmt"
	"runtime"
	"time"
)

func heavy(n int) int {
	// Simulate a CPU-bound computation.
	acc := 0
	for i := 0; i < n; i++ {
		acc += i * i
	}
	return acc
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	nums := make([]int, 1000)
	for i := range nums {
		nums[i] = 100_000
	}

	start := time.Now()
	var total int64
	for _, n := range nums {
		total += int64(heavy(n))
	}
	fmt.Println(total, time.Since(start))

	// All work runs on the single goroutine; even with many cores,
	// the scheduler has nothing to spread. Wall time ≈ sum of all
	// heavy() calls.
}

package main

import (
	"fmt"
	"runtime"
	"sync"
	"time"
)

func heavy(n int) int {
	acc := 0
	for i := 0; i < n; i++ {
		acc += i * i
	}
	return acc
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	const numJobs = 1000
	jobs := make(chan int, numJobs)
	results := make(chan int64, numJobs)

	// Fixed worker pool sized to the CPUs. The scheduler keeps each
	// P busy; idle workers park on the channel without wasting a
	// thread (the G parks, the M is reused).
	var wg sync.WaitGroup
	workers := runtime.NumCPU()
	for range workers {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for n := range jobs {
				results <- int64(heavy(n))
			}
		}()
	}

	go func() {
		for i := 0; i < numJobs; i++ {
			jobs <- 100_000
		}
		close(jobs)
	}()

	go func() {
		wg.Wait()
		close(results)
	}()

	start := time.Now()
	var total int64
	for r := range results {
		total += r
	}
	fmt.Println(total, time.Since(start))
}
